<?php

defined( 'ABSPATH' ) || exit;

/**
 * Serves https://shop.example/llms.txt and https://shop.example/llms-full.txt with content generated by FeedTrix.
 *
 * A local copy in a transient (1 day by default, set from FeedTrix) protects against API latency. FeedTrix drops it through
 * POST /wp-json/feedtrix/purge after every catalog change; the main cache
 * (Redis + Cloudflare, 24 h, invalidated on every change) runs on the FeedTrix side.
 * The last valid version is the fallback when the API is not responding
 * (not when the FeedTrix subscription is inactive: HTTP 402 removes it and the plugin answers 404).
 *
 * GET {endpoint}/shops/{store_key}/llms.txt, …/llms-full.txt (table of contents), …/llms-full/{n}.txt (100 products each)
 */
final class FeedTrix_Llms_Txt {

	private const QUERY_VAR = 'feedtrix_llms_txt';
	private const TRANSIENT = 'feedtrix_llms_txt';
	private const STALE_OPT = 'feedtrix_llms_txt_stale';

	/** @var FeedTrix_Settings */
	private $settings;
	/** @var FeedTrix_Client */
	private $client;

	public function __construct(
		FeedTrix_Settings $settings,
		FeedTrix_Client $client
	) {
		$this->settings = $settings;
		$this->client = $client;
	}

	/** Highest /llms-full/{n}.txt number served from a local copy (used to clear the copies). */
	private const PAGES_OPT = 'feedtrix_llms_full_pages';

	public static function add_rewrite_rule(): void {
		add_rewrite_rule( '^llms\.txt$', 'index.php?' . self::QUERY_VAR . '=1', 'top' );
		add_rewrite_rule( '^llms-full\.txt$', 'index.php?' . self::QUERY_VAR . '=full', 'top' );
		add_rewrite_rule( '^llms-full/([1-9][0-9]{0,3})\.txt$', 'index.php?' . self::QUERY_VAR . '=full-$matches[1]', 'top' );
	}

	/**
	 * Query var value => FeedTrix API path: 1 = llms.txt, full = table of contents, full-N = file number N.
	 */
	private static function api_path( string $file ): ?string {
		if ( '1' === $file ) {
			return 'llms.txt';
		}
		if ( 'full' === $file ) {
			return 'llms-full.txt';
		}
		if ( 1 === preg_match( '/^full-([1-9][0-9]{0,3})$/', $file, $m ) ) {
			return 'llms-full/' . $m[1] . '.txt';
		}

		return null;
	}

	public static function purge_local(): void {
		delete_transient( self::TRANSIENT );
		delete_transient( self::TRANSIENT . '_full' );
		for ( $page = 1, $max = (int) get_option( self::PAGES_OPT, 0 ); $page <= $max; ++$page ) {
			delete_transient( self::TRANSIENT . '_full-' . $page );
		}
	}

	private static function suffix( string $file ): string {
		return '1' === $file ? '' : '_' . $file;
	}

	public function register(): void {
		add_action( 'init', array( self::class, 'add_rewrite_rule' ) );
		add_filter( 'query_vars', array( $this, 'query_vars' ) );
		add_action( 'template_redirect', array( $this, 'serve' ), 0 );
		// no redirect from /llms.txt to /llms.txt/
		add_filter( 'redirect_canonical', array( $this, 'no_canonical_redirect' ) );
		add_action( 'update_option_' . FeedTrix_Settings::OPTION, array( self::class, 'purge_local' ) );
	}

	/** @param string[] $vars */
	public function query_vars( array $vars ): array {
		$vars[] = self::QUERY_VAR;

		return $vars;
	}

	/** @param string|false $redirect */
	public function no_canonical_redirect( $redirect ) {
		return get_query_var( self::QUERY_VAR ) ? false : $redirect;
	}

	public function serve(): void {
		$file = (string) get_query_var( self::QUERY_VAR );
		$path = self::api_path( $file );
		if ( null === $path ) {
			return;
		}

		header( 'X-Generator: FeedTrix' );

		if ( ! $this->settings->llms_txt_enabled() || ! $this->settings->is_connected() ) {
			status_header( 404 );
			nocache_headers();
			header( 'Content-Type: text/plain; charset=utf-8' );
			echo "Not found\n";
			exit;
		}

		$missing = false;
		$content = $this->content( $file, $path, $missing );

		if ( $missing ) { // e.g. /llms-full/9.txt for a catalog of 3 files
			status_header( 404 );
			header( 'Content-Type: text/plain; charset=utf-8' );
			echo "Not found\n";
			exit;
		}
		if ( null === $content ) {
			status_header( 503 );
			header( 'Retry-After: 300' );
			header( 'Content-Type: text/plain; charset=utf-8' );
			echo "Temporarily unavailable\n";
			exit;
		}

		status_header( 200 );
		header( 'Content-Type: text/plain; charset=utf-8' );
		header( 'Cache-Control: public, max-age=300' );
		header( 'X-Robots-Tag: noindex' );
		echo $content; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- plain text
		exit;
	}

	/**
	 * Backup copy (last valid version) only for /llms.txt and the table of contents; catalog files
	 * get only a short local copy, so large stores do not fill up the database.
	 */
	private function content( string $file, string $path, bool &$missing ): ?string {
		$transient = self::TRANSIENT . self::suffix( $file );
		$page      = str_starts_with( $file, 'full-' ) ? (int) substr( $file, 5 ) : 0;
		$stale_opt = $page ? null : self::STALE_OPT . self::suffix( $file );
		$cached    = get_transient( $transient );
		if ( is_string( $cached ) && '' !== $cached ) {
			return $cached;
		}

		$response = $this->client->get( '/shops/' . rawurlencode( $this->settings->shop_id() ) . '/' . $path, $page ? 15 : 5 );
		$code     = is_wp_error( $response ) ? 0 : (int) wp_remote_retrieve_response_code( $response );

		if ( 200 === $code ) {
			$body = (string) wp_remote_retrieve_body( $response );
			if ( '' !== $body ) {
				set_transient( $transient, $body, $this->settings->llms_cache_ttl() );
				if ( $stale_opt ) {
					update_option( $stale_opt, $body, false );
				}
				if ( $page > (int) get_option( self::PAGES_OPT, 0 ) ) {
					update_option( self::PAGES_OPT, $page, false );
				}

				return $body;
			}
		}
		if ( 402 === $code ) {
			// FeedTrix subscription inactive: the files are not served, the backup copy is removed
			if ( $stale_opt ) {
				delete_option( $stale_opt );
			}
			$missing = true;

			return null;
		}
		if ( 404 === $code && $page ) {
			$missing = true;

			return null;
		}
		if ( ! $stale_opt ) {
			return null;
		}

		$stale = get_option( $stale_opt );
		if ( is_string( $stale ) && '' !== $stale ) {
			// short transient, so a failing API is not called on every request
			set_transient( $transient, $stale, 60 );

			return $stale;
		}

		return null;
	}
}
